# Integer (int) -> Whole numbers
students = 156
print(type(students))  # Tells you the type: <class 'int'>

# Float (float) -> Numbers with decimals
accuracy = 0.98
print(type(accuracy))  # Tells you the type: <class 'float'>

# String (str) -> Text (always put inside quotes "")
topic = "Machine Learning"
print(type(topic))     # Tells you the type: <class 'str'>

# Boolean (bool) -> True or False (capital T and F)
is_easy = False
print(type(is_easy))   # Tells you the type: <class 'bool'>
